#define NUM_NOISE_OCTAVES 12

float rand(vec2 co)
{
  return fract(sin(dot(co.xy, vec2(12.9898,78.233))) * 43758.5453);
}

//thanks Morgan McGuire for noise implementations
float noise(vec2 x) {
    vec2 i = floor(x);
    vec2 f = fract(x);

	// Four corners in 2D of a tile
	float a = rand(i);
    float b = rand(i + vec2(1.0, 0.0));
    float c = rand(i + vec2(0.0, 1.0));
    float d = rand(i + vec2(1.0, 1.0));

    vec2 u = f * f * (3.0 - 2.0 * f);
	return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

float fbm(vec2 x) {
	float v = 0.0;
	float a = 0.5;
	vec2 shift = vec2(100);
	// Rotate to reduce axial bias
    mat2 rot = mat2(cos(0.5), sin(0.5), -sin(0.5), cos(0.50));
	for (int i = 0; i < NUM_NOISE_OCTAVES; ++i) {
		v += a * noise(x);
		x = rot * x * 2.0 + shift;
		a *= 0.5;
	}
	return v;
}
//

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = (fragCoord/iResolution.xy);

    vec2 q;

    q.x = fbm((uv*4.0));
    q.y = fbm((uv*4.0));

    float f = fbm(q+uv)*iTime; //remove iTime for normal

    vec3 colorF = vec3(
        0.1 + 0.5 * cos(f * 10.0),  //R
        0.2 + 0.3 * cos(f * 10.0),  //G
        0.6 + 0.4 * cos(f * 10.0)   //B
    );

    // Output to screen
    fragColor = vec4(colorF,1.0);
}
